get_product_page.code:
var response = await client.ProductPage.GetProductPageAsync();
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var productPage = (IReadOnlyDictionary<string, object?>)body["product_page"]!;
var configuration = (IReadOnlyDictionary<string, object?>)productPage["configuration"]!;
var details = (IReadOnlyDictionary<string, object?>)configuration["details"]!;
Console.WriteLine(details["display_description"]);

patch_product_page.code:
var response = await client.ProductPage.PatchProductPageAsync(new Dictionary<string, object?>
{
    ["product_page"] = new Dictionary<string, object?>
    {
        ["configuration"] = new Dictionary<string, object?>
        {
            ["details"] = new Dictionary<string, object?> { ["display_description"] = true },
        },
        ["up_sell"] = new Dictionary<string, object?> { ["short_description"] = true },
    },
});
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var productPage = (IReadOnlyDictionary<string, object?>)body["product_page"]!;
var upSell = (IReadOnlyDictionary<string, object?>)productPage["up_sell"]!;
Console.WriteLine(upSell["short_description"]);

